  const n = Math.min(ac.length, bc.length)
  for (let i = 0; i < n; i++) {
    const x = ac[i].codePointAt(0)
    const y = bc[i].codePointAt(0)
    if (x !== y) return x < y ? -1 : 1
  }
  return ac.length === bc.length ? 0 : (ac.length < bc.length ? -1 : 1)
