{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { readFileSync } from 'node:fs'
import { parse, count, render, ElectionError } from './election.js'

function die (message) {
  process.stderr.write(message + '\n')
  process.exitCode = 2
}

const argv = process.argv.slice(2)
if (argv.length !== 1 || (argv[0] !== 'rounds' && argv[0] !== 'tally')) {
  die('error: usage: cli.js rounds|tally')
} else {
  let input = ''
  try {
    input = readFileSync(0, 'utf8')
  } catch {
    input = ''
  }
  try {
    process.stdout.write(render(argv[0], count(parse(input))))
    process.exitCode = 0
  } catch (error) {
    if (error instanceof ElectionError) die(error.message)
    else throw error
  }
}
"}

