import readline from 'readline';

// Parse command line arguments
const mode = process.argv[2];
if (!mode || !['rounds', 'tally'].includes(mode)) {
  process.stderr.write('error: usage: cli.js rounds|tally\n');
  process.exit(2);
}

// Read all input from stdin
let input = '';
process.stdin.setEncoding('utf8');

process.stdin.on('data', chunk => {
  input += chunk;
});

process.stdin.on('end', () => {
  try {
    const result = runElection(input, mode);
    console.log(result);
    process.exit(0);
  } catch (error) {
    process.stderr.write(error.message + '\n');
    process.exit(2);
  }
});

function runElection(input, mode) {
  // Parse input
  const lines = input.split('\n');
  // Drop the empty tail a trailing newline leaves
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop();
  }

  // Process lines - trim and filter
  const processedLines = [];
  let lineNumber = 0;
  for (const line of lines) {
    lineNumber++;
    const trimmed = line.trim();
    // Ignore empty lines and lines starting with #
    if (trimmed === '' || trimmed.startsWith('#')) {
      continue;
    }
    processedLines.push({ line: trimmed, number: lineNumber });
  }

  let candidates = null;
  let candidatesLineNum = null;
  const ballots = [];

  // Parse candidates and ballots
  for (const { line, number } of processedLines) {
    const parts = line.split(/\s+/);
    if (parts.length === 0) continue;

    const directive = parts[0];

    if (directive === 'candidates') {
      if (candidates !== null) {
        throw new Error(`error: line ${number}: candidates must be declared once, before any ballot`);
      }
      if (parts.length < 2) {
        throw new Error(`error: line ${number}: expected candidates <name>...`);
      }
      const candidateNames = parts.slice(1);
      // Validate candidate names
      for (const name of candidateNames) {
        if (!/^[A-Za-z0-9_-]+$/.test(name)) {
          throw new Error(`error: line ${number}: invalid candidate name ${name}`);
        }
      }
      // Check for duplicates
      const uniqueNames = new Set(candidateNames);
      if (uniqueNames.size !== candidateNames.length) {
        for (const name of candidateNames) {
          if (candidateNames.indexOf(name) !== candidateNames.lastIndexOf(name)) {
            throw new Error(`error: line ${number}: candidate ${name} is declared twice`);
          }
        }
      }
      candidates = candidateNames;
      candidatesLineNum = number;
    } else if (directive === 'ballot') {
      if (candidates === null) {
        throw new Error(`error: line ${number}: candidates must be declared once, before any ballot`);
      }
      if (parts.length < 2) {
        throw new Error(`error: line ${number}: expected ballot <count> <candidate>...`);
      }

      // Parse count
      const countStr = parts[1];
      let count;
      try {
        count = parseInt(countStr, 10);
        // Must be positive, no leading zero, no sign
        if (count < 1 || countStr !== count.toString()) {
          throw new Error('invalid');
        }
      } catch {
        throw new Error(`error: line ${number}: count must be a positive integer`);
      }

      const ballotCandidates = parts.slice(2);
      if (ballotCandidates.length === 0) {
        throw new Error(`error: line ${number}: expected ballot <count> <candidate>...`);
      }

      // Validate candidates
      const candidateSet = new Set(candidates);
      const seenBallotCandidates = new Set();
      for (const name of ballotCandidates) {
        if (!candidateSet.has(name)) {
          throw new Error(`error: line ${number}: unknown candidate ${name}`);
        }
        if (seenBallotCandidates.has(name)) {
          throw new Error(`error: line ${number}: candidate ${name} is repeated`);
        }
        seenBallotCandidates.add(name);
      }

      ballots.push({ count, candidates: ballotCandidates });
    } else {
      throw new Error(`error: line ${number}: unknown directive ${directive}`);
    }
  }

  // Check if candidates were declared
  if (candidates === null) {
    throw new Error('error: no candidates');
  }

  // Run the election
  const rounds = [];
  let continuing = new Set(candidates);
  const candidateHistory = {}; // Track vote counts across rounds for tiebreaking
  for (const candidate of candidates) {
    candidateHistory[candidate] = [];
  }

  while (true) {
    // Count votes in this round
    const votes = {};
    let exhausted = 0;

    for (const candidate of continuing) {
      votes[candidate] = 0;
    }

    for (const ballot of ballots) {
      let counted = false;
      for (let i = 0; i < ballot.candidates.length; i++) {
        if (continuing.has(ballot.candidates[i])) {
          votes[ballot.candidates[i]] += ballot.count;
          counted = true;
          break;
        }
      }
      if (!counted) {
        exhausted += ballot.count;
      }
    }

    // Record this round
    const activeTotal = Object.values(votes).reduce((a, b) => a + b, 0);
    const roundData = {
      votes: votes,
      exhausted: exhausted,
      activeTotal: activeTotal
    };

    // Track vote counts for all candidates (including those not yet eliminated)
    for (const candidate of candidates) {
      if (continuing.has(candidate)) {
        candidateHistory[candidate].push(votes[candidate]);
      }
    }

    rounds.push(roundData);

    // Check for winner
    if (activeTotal === 0) {
      // No winner
      break;
    }

    // Check for majority
    let winner = null;
    for (const candidate of continuing) {
      if (votes[candidate] * 2 > activeTotal) {
        winner = candidate;
        break;
      }
    }

    if (winner) {
      break;
    }

    // Find candidate to eliminate
    // The one with the fewest votes
    let minVotes = Infinity;
    let candidates_with_min = [];
    for (const candidate of continuing) {
      if (votes[candidate] < minVotes) {
        minVotes = votes[candidate];
        candidates_with_min = [candidate];
      } else if (votes[candidate] === minVotes) {
        candidates_with_min.push(candidate);
      }
    }

    // Tiebreaker: compare across rounds
    const toEliminate = breakTie(candidates_with_min, candidateHistory);
    continuing.delete(toEliminate);
    roundData.eliminated = toEliminate;
  }

  // Generate output
  let output = '';

  if (mode === 'rounds') {
    // Print each round
    for (let i = 0; i < rounds.length; i++) {
      const round = rounds[i];
      output += `round ${i + 1}: `;

      // Get all candidates for this round and sort them
      const roundVotes = [];
      for (const candidate of candidates) {
        if (i < candidateHistory[candidate].length) {
          roundVotes.push({
            name: candidate,
            votes: candidateHistory[candidate][i]
          });
        }
      }

      // Sort by descending votes, then ascending name
      roundVotes.sort((a, b) => {
        if (b.votes !== a.votes) {
          return b.votes - a.votes;
        }
        return a.name.localeCompare(b.name);
      });

      const voteStrs = roundVotes.map(v => `${v.name}=${v.votes}`);
      output += voteStrs.join(' ');
      output += ` exhausted=${round.exhausted}\n`;

      if (round.eliminated) {
        output += `eliminated ${round.eliminated}\n`;
      }
    }
  } else {
    // tally mode
    output += `rounds ${rounds.length}\n`;
  }

  // Determine winner
  if (rounds.length > 0 && rounds[rounds.length - 1].activeTotal === 0) {
    output += 'no winner\n';
  } else if (rounds.length === 0 || Object.values(rounds[rounds.length - 1].votes).every(v => v === 0)) {
    output += 'no winner\n';
  } else {
    // Find winner
    const lastRound = rounds[rounds.length - 1];
    let winner = null;
    for (const candidate of candidates) {
      if (lastRound.votes && lastRound.votes[candidate] * 2 > lastRound.activeTotal) {
        winner = candidate;
        break;
      }
    }

    if (winner) {
      output += `winner ${winner}\n`;
    } else {
      output += 'no winner\n';
    }
  }

  return output.trimEnd();
}

function breakTie(candidates, candidateHistory) {
  if (candidates.length === 1) {
    return candidates[0];
  }

  // Compare across rounds from first to last
  const roundCount = Object.values(candidateHistory)[0].length;

  for (let roundIdx = 0; roundIdx < roundCount; roundIdx++) {
    // Get vote counts for this round for all tied candidates
    const votes = [];
    for (const candidate of candidates) {
      if (roundIdx < candidateHistory[candidate].length) {
        votes.push({
          candidate: candidate,
          votes: candidateHistory[candidate][roundIdx]
        });
      }
    }

    // Find minimum votes in this round among tied candidates
    let minVotes = Infinity;
    for (const v of votes) {
      if (v.votes < minVotes) {
        minVotes = v.votes;
      }
    }

    // Keep only those with minimum votes
    const filtered = votes.filter(v => v.votes === minVotes).map(v => v.candidate);

    if (filtered.length === 1) {
      return filtered[0];
    }

    // Otherwise continue with these as the new tied set
    candidates = filtered;
  }

  // If still tied after all rounds, eliminate by code point (last alphabetically)
  candidates.sort((a, b) => b.localeCompare(a));
  return candidates[0];
}

